/**
 * Preclinical model availability: which cell lines, patient-derived xenografts (PDX), genetically engineered mouse
 * models (GEMMs) and organoid banks exist for each cancer and for the targets where genotype matters.
 *
 * Cell-line identifiers (Cellosaurus accession, DepMap ACH id, NCIt disease) are resolved by name from the
 * Cellosaurus API into `src/data/cell-line-ids.ts` (generated by scripts/fetch-cell-lines.ts); nothing is typed by
 * hand. Cell-line names follow Cellosaurus spelling. Repository links point at the portal, not at a specific model,
 * because model catalogues change weekly. GEMM rows cite the paper that described the model or the Mouse Tumor
 * Biology database entry.
 *
 * Rendered at /preclinical-models/ and on target dossiers.
 */
import { CELL_LINE_IDS, type CellLineIds } from "./cell-line-ids";

export type CellLine = { name: string; note: string; /** Target ids whose genotype this line models. */ targets?: string[] };
export type Repository = { name: string; url: string; note: string };
export type Gemm = { name: string; alleles: string; note: string; source: { label: string; url: string } };
export type ModelEntry = {
  /** Cancer id or target id. */
  subject: string;
  cellLines: CellLine[];
  pdx: Repository[];
  gemms: Gemm[];
  organoids: Repository[];
  caveats?: string[];
};

const doi = (d: string, label: string) => ({ label, url: `https://doi.org/${d}` });
const pmid = (id: string, label: string) => ({ label, url: `https://pubmed.ncbi.nlm.nih.gov/${id}/` });
const MTB = { label: "Mouse Tumor Biology database (JAX)", url: "https://tumor.informatics.jax.org/mtbwi/index.do" };

/** Shared repositories. */
export const REPOS = {
  pdmr: { name: "NCI Patient-Derived Models Repository (PDMR)", url: "https://pdmr.cancer.gov/", note: "Free-to-academics PDX, organoid and cell-line models with clinical annotation and sequencing." },
  pdxnet: { name: "PDXNet", url: "https://www.pdxnetwork.org/", note: "NCI consortium coordinating PDX development and co-clinical trials across US centres." },
  europdx: { name: "EurOPDX", url: "https://www.europdx.eu/", note: "European PDX consortium; models discoverable through the PDCM Finder." },
  champions: { name: "Champions Oncology", url: "https://www.championsoncology.com/", note: "Commercial bank of over 1,500 characterised PDX models (Lumin platform)." },
  jax: { name: "JAX PDX resource", url: "https://tumor.informatics.jax.org/mtbwi/pdxSearch.do", note: "Jackson Laboratory PDX collection with searchable genomics." },
  pdcm: { name: "PDCM Finder (cancermodels.org)", url: "https://www.cancermodels.org/", note: "EMBL-EBI and JAX meta-catalogue of PDX, organoid and cell-line models from dozens of providers." },
  hcmi: { name: "Human Cancer Models Initiative (HCMI)", url: "https://hcmi-searchable-catalog.nci.nih.gov/", note: "Next-generation organoid and conditionally reprogrammed models distributed through ATCC with matched sequencing." },
  hub: { name: "HUB Organoids", url: "https://www.huborganoids.nl/", note: "Hubrecht-founded biobank of patient-derived organoids across tumour types; academic and commercial access." },
  sanger: { name: "Sanger Cell Model Passports", url: "https://cellmodelpassports.sanger.ac.uk/", note: "Genomic and phenotypic passports for over 2,000 cell lines and organoids, including the Sanger organoid collection." },
  depmap: { name: "DepMap portal", url: "https://depmap.org/portal/", note: "Genome-wide CRISPR dependency and drug-sensitivity data on over 1,000 cell lines; the first place to check whether a target is essential in a lineage." },
  ccle: { name: "CCLE / DepMap omics", url: "https://depmap.org/portal/data_page/", note: "Expression, mutation, copy number and proteomics for the DepMap cell-line set." },
} satisfies Record<string, Repository>;

const STANDARD_PDX = [REPOS.pdmr, REPOS.pdcm, REPOS.champions];
