/** Resolved identifiers for a cell line by Cellosaurus spelling; undefined when the name was not resolved. */
export function cellLineIds(name: string): CellLineIds | undefined {
  return CELL_LINE_IDS[name];
}

/** Every distinct cell-line name in the registry (used by the fetch script and the page). */
export function allCellLineNames(): string[] {
  return [...new Set(preclinicalModels.flatMap((m) => m.cellLines.map((c) => c.name)))].sort();
}

export const modelsFor = (subject: string): ModelEntry | undefined => preclinicalModels.find((m) => m.subject === subject);
